import { App } from "@slack/bolt";

const app = new App({
  token: process.env.SLACK_BOT_TOKEN,
  appToken: process.env.SLACK_APP_TOKEN,
  socketMode: true,
});

app.command("/nova", async ({ ack, command, respond }) => {
  await ack();
  const [verb, key] = parseNova(command.text); // "/nova RH-1234" means start
  const by = people.bySlackId(command.user_id);
  const run = temporal.workflow.getHandle(`nova:${key}`);
  if (verb === "start") await startRun(temporal, "nova", key, ticketToPr, { key, requester: by });
  if (verb === "status") await respond(oneLine(await run.query("status")));
  if (verb === "stop") await run.signal("stop", by);
});

await app.start(); // dials out to Slack; no port is opened

app.action("plan_approve", async ({ ack, body, action, client }) => {
  await ack();
  if (body.type !== "block_actions" || action.type !== "button") return;
  const [workflowId = "", version = ""] = (action.value ?? "").split("|");
  const person = people.bySlackId(body.user.id);
  if (!(await isRequester(person, workflowId))) {
    return ephemeral(client, body, "Only the person who asked for this ticket can decide its plan.");
  }
  try {
    await temporal.workflow.getHandle(workflowId).signal(decidePlan, { kind: "approve", by: person.email, version });
  } catch {
    return ephemeral(client, body, "That didn't reach Nova. Please try again in a minute.");
  }
  await client.chat.update({
    channel: body.channel?.id ?? "", ts: body.message?.ts ?? "",
    text: `Plan ${version} approved by ${person.name}`, blocks: [],
  });
});

