const requesters = {}; // workflow ID -> Slack ID of the person who asked

app.command("/nova", async ({ ack, command, client }) => {
  await ack();
  const key = command.text.trim().toUpperCase();
  requesters[`nova:${key}`] ??= command.user_id;
  await temporal.start(`nova:${key}`);
  await client.chat.postMessage({
    channel: command.channel_id,
    text: `${key}: plan v2 is ready for your OK`,
    blocks: [
      { type: "section", text: { type: "mrkdwn", text: `*${key}* · plan v2 is ready for your OK` } },
      { type: "actions", elements: [{ type: "button", action_id: "plan_approve", value: `nova:${key}|v2`,
        text: { type: "plain_text", text: "Approve" } }] },
    ],
  });
});

app.action("plan_approve", async ({ ack, body, action, client }) => {
  await ack();
  const [workflowId, version] = action.value.split("|");
  if (body.user.id !== requesters[workflowId]) {
    await client.chat.postEphemeral({ channel: body.channel.id, user: body.user.id,
      text: `Only <@${requesters[workflowId]}> can decide this plan.` });
    return;
  }
  await temporal.signal(workflowId, "decidePlan", { kind: "approve", by: body.user.id, version });
  await client.chat.update({ channel: body.channel.id, ts: body.message.ts,
    text: `${workflowId} ${version}: approved by ${body.user.id}`, blocks: [] });
});
